"use strict";
  function renderHealth(){
    const r=routeInfo();const service=r.params.get("service");const healthGroup=D.serviceGroups.find(x=>x.key==="health");const temporary=D.listings.filter(x=>x.group==="health"&&(!service||publicSubcategory(x.subcategory)===service));
    main.innerHTML=pageIntro("Услуги → Здраве и грижа","Здраве и грижа","Един публичен здравен вход с два ясно различни типа съдържание: проверени специалисти/практики и временни здравни услуги.",button("Добави специалист или практика","health-proposal","button button-primary")+button("Публикувай или потърси здравна услуга",`listing-form?main=services&group=health${service?`&leaf=${encodeURIComponent(service)}`:""}`))+`<section class="section"><div class="shell">${crumb([["Обяви и услуги","marketplace"],["Услуги","marketplace/services"],["Здраве и грижа",""]])}<div class="health-dual"><div class="health-panel"><span class="badge badge-ok">Проверена информация</span><h2>Специалисти и практики</h2><p>Health/Info owner. Профилите не са обяви и не се превръщат автоматично във фирмени или marketplace записи.</p><div class="result-list">${D.healthProviders.map(h=>`<article class="result-card"><div><span class="owner-label">Health / Info</span><h3>${esc(h.name)}</h3><p>${esc(h.specialty)}</p><div class="result-meta">${statusBadge(h.status)}<span>${esc(h.kind)}</span><span>${esc(h.address)}</span></div></div><div class="result-actions"><button class="button button-primary" type="button" data-action="call" data-phone="${esc(h.phone)}">Обади се</button><button class="button button-soft" type="button" data-route="health-provider/${h.id}">Информация</button></div></article>`).join("")}</div><div class="mt-12">${button("Добави специалист или практика","health-proposal","button button-primary")}</div></div><div class="health-panel"><span class="badge badge-blue">Обяви за услуги</span><h2>Здравни услуги</h2><p>Временни предложения и търсения през Listings owner-а. Публикацията не получава статус „проверен специалист“.</p><div class="health-services">${healthGroup.leaves.map(l=>`<button class="health-service" type="button" data-route="marketplace/services?group=health&service=${encodeURIComponent(l)}">${esc(l)}</button>`).join("")}</div></div></div>${service?`<div class="divider"></div>${listingBrowse({title:service,text:"Временни предложения и търсения за избраната здравна услуга.",rows:temporary,baseRoute:`marketplace/services?group=health&service=${encodeURIComponent(service)}`})}`:""}<div class="notice notice-info mt-16"><strong>Ясна граница на доверие</strong>Провереният здравен профил и временната обява могат да са на една публична страница, но остават отделни записи с отделни owners и отделно значение.</div></div></section>`;
  }
  function renderHealthProvider(id){const h=D.healthProviders.find(x=>x.id===id);if(!h)return renderNotFound();main.innerHTML=pageIntro("Здраве и грижа",h.name,h.specialty,`<button class="button button-primary" type="button" data-action="call" data-phone="${esc(h.phone)}">Обади се</button>`+`<button class="button button-soft" type="button" data-share="health-provider/${h.id}" data-share-title="${esc(h.name)}">Сподели</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Услуги","marketplace/services"],["Здраве и грижа","marketplace/services?group=health"],[h.name,""]])}<div class="detail-block trust-strip"><strong>Проверен Health/Info запис</strong><br>${esc(h.confirmed)} · Източник: ${esc(h.source)}</div><div class="detail-block"><h2>Информация</h2><div class="facts"><div class="fact"><span>Тип</span><strong>${esc(h.kind)}</strong></div><div class="fact"><span>Специалност</span><strong>${esc(h.specialty)}</strong></div><div class="fact"><span>Адрес</span><strong>${esc(h.address)}</strong></div><div class="fact"><span>Телефон</span><strong>${esc(h.phone)}</strong></div></div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" type="button" data-action="call" data-phone="${esc(h.phone)}">Обади се</button><button class="button button-outline" type="button" data-route="correction?target=${encodeURIComponent(h.name)}&owner=health">Предложи корекция</button><button class="button button-outline" type="button" data-share="health-provider/${h.id}" data-share-title="${esc(h.name)}">Сподели</button></div></aside></div></section>`}
  function renderHealthProposal(){main.innerHTML=pageIntro("Health / Info owner","Добави специалист или практика","Специализирано предложение. Не е фирмена форма и не е обява.")+`<section class="section"><div class="shell form-wrap"><div class="form-card"><div class="notice notice-info"><strong>Публикуване след преглед</strong>След изпращане предложението остава pending и се публикува само след Admin review.</div><form class="form-grid proto-form mt-16" data-form="health-proposal"><fieldset class="field field-full"><legend>Тип</legend><div class="choice-grid"><div class="choice"><input id="hp-doctor" name="type" type="radio" value="Лекар" required checked><label for="hp-doctor"><strong>Лекар</strong><small>Специалист или личен лекар</small></label></div><div class="choice"><input id="hp-dentist" name="type" type="radio" value="Стоматолог"><label for="hp-dentist"><strong>Стоматолог</strong><small>Дентална практика</small></label></div><div class="choice"><input id="hp-vet" name="type" type="radio" value="Ветеринар"><label for="hp-vet"><strong>Ветеринар</strong><small>Ветеринарен специалист/кабинет</small></label></div></div></fieldset>${field("Име","name",{required:true,min:3,placeholder:"Име на специалиста или практиката"})}${field("Специалност","specialty",{required:true,min:3})}${field("Телефон","phone",{required:true,type:"tel",placeholder:"0... или +359..."})}${field("Адрес","address",{required:true,min:3})}${field("Допълнителна информация","notes",{textarea:true,full:true,required:true,min:20})}<label class="check-row field-full"><input type="checkbox" name="consent" required> Потвърждавам, че подавам информация за проверка и разбирам, че тя няма да се публикува автоматично.</label><div class="form-actions"><button class="button button-outline" type="button" data-route="marketplace/services?group=health">Отказ</button><button class="button button-primary" type="submit">Изпрати за одобрение</button></div></form></div></div></section>`;bindFormUX()}

  function renderListingDetail(id){const l=D.listings.find(x=>x.id===id);if(!l)return renderNotFound();const shareAllowed=l.status==="approved";main.innerHTML=pageIntro("Обява",l.title,`${l.type} · ${l.category}`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Обяви и услуги","marketplace"],[l.title,""]])}<div class="detail-title"><div class="flex">${statusBadge(l.status)}${l.ownerType==="firm"?`<span class="badge badge-blue">Фирмена обява</span>`:""}</div><h1>${esc(l.title)}</h1><p>${esc(l.description)}</p><div class="tag-row"><span class="badge">${esc(l.type)}</span><span class="badge">${esc(l.city)}</span>${l.subcategory?`<span class="badge">${esc(publicSubcategory(l.subcategory))}</span>`:""}</div></div><div class="detail-block"><h2>Описание</h2><p>${esc(l.description)}</p></div><div class="detail-block"><h2>Снимки</h2><div class="photo-preview">${Array.from({length:Math.max(1,l.photos||0)},(_,i)=>`<span>${l.photos?`Снимка ${i+1}`:"Няма снимки"}</span>`).join("")}</div></div>${l.status!=="approved"?`<div class="notice notice-warn"><strong>Тази публикация не е публична</strong>Споделянето към Facebook/други канали е недостъпно, докато няма одобрен canonical public record.</div>`:""}</div><aside class="detail-side"><div class="detail-block detail-actions"><div class="price mb-0">${esc(l.price||"Цена не е посочена")}</div><button class="button button-primary" type="button" data-action="call" data-phone="${esc(l.phone)}">Покажи / позвъни</button>${shareAllowed?`<button class="button button-outline" type="button" data-share="listing/${l.id}" data-share-title="${esc(l.title)}">Сподели</button>`:`<button class="button button-outline" type="button" disabled title="Достъпно след одобрение">Сподели след одобрение</button>`}<button class="button button-outline" type="button" data-route="report?target=${encodeURIComponent(l.title)}&owner=listing">Докладвай</button><button class="button button-soft" type="button" data-route="listing-form?edit=${l.id}">Редактирай (прототип)</button></div><div class="detail-block"><h2>Публикувано от</h2><p class="mt-0"><strong>${esc(l.owner)}</strong><br><span class="muted">${l.ownerType==="firm"?"Одобрена фирма":"Лична обява"}</span></p></div></aside></div></section>`}

  function serviceLeafOptions(){return D.serviceGroups.flatMap(g=>g.leaves.map(l=>({group:g.key,label:l})))}
  function field(label,name,o={}){const type=o.type||"text",id=`f-${name}`;return `<div class="field ${o.full?"field-full":""}" data-field="${esc(name)}"><label for="${id}">${esc(label)}${o.required?" *":""}</label>${o.textarea?`<textarea id="${id}" name="${esc(name)}" ${o.required?"required":""} ${o.min?`minlength="${o.min}"`:""} ${o.max?`maxlength="${o.max}"`:""} placeholder="${esc(o.placeholder||"")}">${esc(o.value||"")}</textarea>`:`<input id="${id}" name="${esc(name)}" type="${esc(type)}" ${o.required?"required":""} ${o.min?`minlength="${o.min}"`:""} ${o.max?`maxlength="${o.max}"`:""} ${o.minNum!=null?`min="${o.minNum}"`:""} value="${esc(o.value||"")}" placeholder="${esc(o.placeholder||"")}" autocomplete="${esc(o.autocomplete||"off")}">`}${o.help?`<small>${esc(o.help)}</small>`:""}<small class="field-error" data-error-for="${esc(name)}" aria-live="polite"></small></div>`}
  function selectField(label,name,options,value="",o={}){return `<div class="field ${o.full?"field-full":""}" data-field="${esc(name)}"><label for="f-${esc(name)}">${esc(label)}${o.required?" *":""}</label><select id="f-${esc(name)}" name="${esc(name)}" ${o.required?"required":""}><option value="">${esc(o.placeholder||"Избери")}</option>${options.map(x=>{const v=typeof x==="string"?x:x.value,lab=typeof x==="string"?x:x.label;return `<option value="${esc(v)}" ${String(value)===String(v)?"selected":""}>${esc(lab)}</option>`}).join("")}</select><small class="field-error" data-error-for="${esc(name)}" aria-live="polite"></small></div>`}
  function listingPublicMain(value){return ({services:"Услуги",vehicles:"Автомобили",work:"Работа",property:"Имоти",trade:"Купува и продава"})[value]||value}
  function renderListingForm(){const r=routeInfo(),editId=r.params.get("edit"),existing=editId?D.listings.find(x=>x.id===editId):null;const mainPref=existing?.main||r.params.get("main")||"";const groupPref=existing?.group||r.params.get("group")||"";const leafPref=existing?publicSubcategory(existing.subcategory||existing.category):r.params.get("leaf")||"";const intentPref=existing?(/Търси|Купува/.test(existing.type)?"seek":"offer"):(r.params.get("intent")||"");const adminExtras=isAdmin()?`<div class="form-section"><h3>Admin-only разширени опции</h3><div class="notice notice-warn"><strong>Защитена зона</strong>Тези контроли се виждат само в Admin режим. Normal user и Moderator никога не ги получават.</div><div class="grid grid-2 mt-12"><label class="check-row"><input type="checkbox" name="urgent"> Спешно</label><label class="check-row"><input type="checkbox" name="reduced"> Намалено</label><label class="check-row"><input type="checkbox" name="boosted"> Горно позициониране</label><label class="check-row"><input type="checkbox" name="highlight"> Открояване</label><label class="check-row"><input type="checkbox" name="stats"> Статистики</label><label class="check-row"><input type="checkbox" name="floating"> Плаващи контактни бутони</label></div><p class="muted small">Admin не използва нормалната квота от 5. Прототипът не превръща текущия технически лимит 20 снимки в бизнес правило.</p></div>`:"";
    const quota=isAdmin()?`<div class="notice notice-ok"><strong>Admin</strong>Direct publish според защитеното правило. Няма нормална месечна квота от 5.</div>`:`<div class="notice notice-info"><strong>${isModerator()?"Moderator — собствено съдържание":"Месечна квота"}</strong>До 5 нови лични обяви за календарен месец; отделно до 5 за всяка собствена одобрена фирма. Редакцията не използва нова квота.</div>`;
    main.innerHTML=pageIntro("Listings owner",existing?"Редактирай обява":"Добави обява",existing?"Редакцията не създава втори запис и не използва нова квота.":"Предлагам/Търся → раздел → подкатегория → детайли. Публикуването следва защитените роля и moderation правила.")+`<section class="section"><div class="shell form-wrap">${crumb([["Обяви и услуги","marketplace"],[existing?"Редактирай":"Добави обява",""]])}<div class="form-card"><div class="progress" aria-label="Стъпки"><span class="done"></span><span class="done"></span><span class="done"></span><span></span></div>${quota}<form class="form-grid proto-form mt-16" data-form="listing" data-edit-id="${esc(editId||"")}">${selectField("Публикувай като","publisher",["Лична обява","Моя одобрена фирма"],existing?.ownerType==="firm"?"Моя одобрена фирма":"Лична обява",{required:true,full:true})}<fieldset class="field field-full"><legend>Какво искаш да направиш? *</legend><div class="choice-grid"><div class="choice"><input id="intent-offer" name="intent" type="radio" value="offer" ${intentPref==="offer"?"checked":""} required><label for="intent-offer"><strong>Предлагам</strong><small>Услуга, работа, имот, автомобил или стока</small></label></div><div class="choice"><input id="intent-seek" name="intent" type="radio" value="seek" ${intentPref==="seek"?"checked":""}><label for="intent-seek"><strong>Търся</strong><small>Услуга, работа, имот, автомобил или стока</small></label></div></div><small class="field-error" data-error-for="intent"></small></fieldset>${selectField("Раздел","main",D.marketplace.map(x=>({value:x.key,label:x.title})),mainPref,{required:true,full:true})}<div id="listing-context-fields" class="field-full form-grid"></div><div id="listing-type-field" class="field-full"></div>${field("Заглавие","title",{required:true,min:5,max:120,full:true,value:existing?.title||"",placeholder:"Опиши конкретно какво предлагаш или търсиш"})}${field("Описание","description",{textarea:true,required:true,min:20,full:true,value:existing?.description||"",placeholder:"Добави важните детайли"})}<div class="field"><label for="f-price">Цена в евро</label><input id="f-price" name="price" type="number" min="0" step="0.01" placeholder="0.00"><small>Ориентировъчното показване в лева е вторично.</small><small class="field-error" data-error-for="price"></small></div><div class="field"><label>Условия</label><label class="check-row"><input type="checkbox" name="negotiable"> Договаряне</label><label class="check-row"><input type="checkbox" name="free"> Подарява / безплатно</label></div>${field("Телефон","phone",{required:true,type:"tel",value:existing?.phone||"",placeholder:"0... или +359..."})}${field("Град / район","city",{required:true,min:2,value:existing?.city||"Лом"})}${field("Улица (по желание)","street",{full:true,placeholder:"Не е задължително"})}<div class="field field-full"><label for="listing-photos">Снимки</label><div class="photo-drop"><input id="listing-photos" name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><strong>До 6 снимки за normal user / Moderator</strong><br><small>JPG, PNG или WebP. В прототипа файловете не се качват никъде.</small><div class="photo-preview" id="listing-photo-preview"></div></div></div>${adminExtras}<label class="check-row field-full"><input type="checkbox" name="consent" required> Прочетох и приемам правилата за публикуване.</label><div class="form-actions"><button class="button button-outline" type="button" data-route="marketplace">Отказ</button><button class="button button-primary" type="submit">${isAdmin()?"Запази и публикувай":existing?"Запази и изпрати за преглед":"Изпрати за преглед"}</button></div></form></div></div></section>`;
    updateListingContext(mainPref,groupPref,leafPref,existing?.type||"");bindFormUX();
  }
  function updateListingContext(mainValue,groupValue="",leafValue="",typeValue=""){
    const holder=document.getElementById("listing-context-fields"),typeHolder=document.getElementById("listing-type-field");if(!holder||!typeHolder)return;let html="";
    if(mainValue==="services"){html+=selectField("Група услуги","service_group",D.serviceGroups.map(g=>({value:g.key,label:g.title})),groupValue,{required:true});const g=D.serviceGroups.find(x=>x.key===(groupValue||"masters"));const options=g?g.leaves:serviceLeafOptions().map(x=>x.label);html+=selectField("Услуга","leaf",options,leafValue,{required:true});}
    if(mainValue==="vehicles")html+=selectField("Автомобил / услуга","leaf",D.autoLeaves,leafValue,{required:true,full:true});
    if(mainValue==="trade")html+=selectField("Категория стоки","leaf",D.tradeLeaves,leafValue,{required:true,full:true});
    holder.innerHTML=html;
    const intent=document.querySelector('[name="intent"]:checked')?.value||"offer";let types=[];
    if(mainValue==="work")types=["Предлага работа","Търси работа"];
    else if(mainValue==="property")types=["Продава имот","Отдава под наем","Търси под наем","Търси за купуване"];
    else if(mainValue==="trade")types=intent==="seek"?["Купува","Търси"]:["Продава","Дава"];
    else if(mainValue==="vehicles"){const leaf=document.querySelector('[name="leaf"]')?.value||leafValue;types=leaf==="Автомобили за продажба или търсене"?(intent==="seek"?["Купува"]:["Продава"]):(intent==="seek"?["Търси"]:["Предлага"])}
    else if(mainValue==="services")types=intent==="seek"?["Търси"]:["Предлага"];
    typeHolder.innerHTML=types.length?selectField(mainValue==="work"?"Тип работа":mainValue==="property"?"Тип имот":"Тип обява","listing_type",types,typeValue&&types.includes(typeValue)?typeValue:types[0],{required:true,full:true}):"";
    bindFormUX();
  }
